package com.campusloop;
import jakarta.servlet.http.HttpSession;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.core.io.FileSystemResource;
import org.springframework.http.MediaType;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.dao.DataAccessException;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.security.SecureRandom;
import java.nio.file.*;
import java.sql.Statement;
import java.sql.PreparedStatement;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
@RestController @RequestMapping("/api") public class Api {
 final JdbcTemplate db; final PasswordEncoder encoder; final SecureRandom rng=new SecureRandom();
 @Value("${campusloop.upload-dir}") String uploadDirectory;
 static final long MAX_ATTACHMENT_BYTES=10L*1024*1024;
 static final Set<String> ATTACHMENT_TYPES=Set.of("jpg","jpeg","png","webp","pdf","doc","docx","ppt","pptx","xls","xlsx","txt","csv");
 Api(JdbcTemplate db,PasswordEncoder encoder){this.db=db;this.encoder=encoder;}
 record Auth(String name,String email,String collegeId,String password,String department,String year){}
 record Profile(String bio){}
 record Post(String kind,String title,String description,String category,Double price,String location,String destination,Integer quantity){}
 record OfferRequest(Integer quantity){}
 record Blog(String title,String body){}
 record SafetyReport(Long postId,Long userId,String category,String details){}
 record Dispute(String details){}
 record LostFoundEntry(String kind,String title,String description,String location){}
 record Announcement(String title,String body){}
 record LocationUpdate(Double latitude,Double longitude){}
 record Message(String body){} record Review(Integer rating,String body){} record ProductReview(Integer rating,String body){} record SupportTicket(String subject,String details){} record Report(Long postId,String reason){}
 long uid(HttpSession s){Object v=s.getAttribute("uid");if(v==null)throw new ApiError(HttpStatus.UNAUTHORIZED,"Please log in");return ((Number)v).longValue();}
 Map<String,Object> one(String sql,Object...args){List<Map<String,Object>> l=db.queryForList(sql,args);if(l.isEmpty())throw new ApiError(HttpStatus.NOT_FOUND,"Not found");return l.get(0);}
 long num(Map<String,Object> m,String key){return ((Number)m.get(key)).longValue();}
 String str(Map<String,Object> m,String key){return String.valueOf(m.get(key));}
 void require(boolean condition,String message){if(!condition)throw new ApiError(HttpStatus.BAD_REQUEST,message);}
 void notifyUser(long user,String msg){notifyUser(user,msg,null,null);}
 void notifyUser(long user,String msg,String targetType,Long targetId){KeyHolder key=new GeneratedKeyHolder();db.update(connection->{PreparedStatement statement=connection.prepareStatement("INSERT INTO notifications(user_id,body) VALUES(?,?)",Statement.RETURN_GENERATED_KEYS);statement.setLong(1,user);statement.setString(2,msg);return statement;},key);if(targetType!=null&&key.getKey()!=null)db.update("INSERT INTO notification_targets(notification_id,event_type,event_id) VALUES(?,?,?)",key.getKey().longValue(),targetType,targetId);}
 boolean validCampusEmail(String email){return email!=null&&email.trim().toLowerCase(Locale.ROOT).matches("^[a-z0-9._%+-]+@kongu\\.edu$");}
 @PostMapping("/register") Map<String,Object> register(@RequestBody Auth a){require(a.name()!=null&&!a.name().isBlank()&&validCampusEmail(a.email())&&a.collegeId()!=null&&!a.collegeId().isBlank()&&a.password()!=null&&a.password().length()>=8,"Register with a valid @kongu.edu email and a password of at least 8 characters");db.update("INSERT INTO users(name,email,college_id,password_hash,department,year_of_study) VALUES(?,?,?,?,?,?)",a.name().trim(),a.email().trim().toLowerCase(),a.collegeId().trim().toUpperCase(),encoder.encode(a.password()),a.department(),a.year());return Map.of("message","Registered. Campus identity is not independently verified.");}
 @PostMapping("/login") Map<String,Object> login(@RequestBody Map<String,String> a,HttpSession s){String email=a.getOrDefault("email","").trim().toLowerCase(Locale.ROOT);require(validCampusEmail(email),"Use your @kongu.edu email to sign in");List<Map<String,Object>> users=db.queryForList("SELECT * FROM users WHERE email=?",email);require(!users.isEmpty()&&encoder.matches(a.getOrDefault("password",""),str(users.get(0),"password_hash"))&&!Boolean.TRUE.equals(users.get(0).get("suspended")),"Invalid credentials or suspended account");s.setAttribute("uid",num(users.get(0),"id"));Map<String,Object> result=new HashMap<>(me(s));String token=UUID.randomUUID().toString()+UUID.randomUUID();db.update("INSERT INTO mobile_tokens(token,user_id) VALUES(?,?)",token,num(users.get(0),"id"));result.put("token",token);return result;}
 @PostMapping("/logout") Map<String,String> logout(HttpSession s){Object token=s.getAttribute("mobileToken");if(token!=null)db.update("DELETE FROM mobile_tokens WHERE token=?",token);s.invalidate();return Map.of("message","Logged out");}
 @GetMapping("/me") Map<String,Object> me(HttpSession s){return one("SELECT id,name,email,college_id,department,year_of_study,bio,is_admin FROM users WHERE id=? AND suspended=FALSE",uid(s));}
 @PostMapping("/profile") Map<String,Object> updateProfile(@RequestBody Profile profile,HttpSession s){require(profile.bio()!=null&&profile.bio().length()<=500,"Bio must be 500 characters or fewer");db.update("UPDATE users SET bio=? WHERE id=?",profile.bio().trim(),uid(s));return me(s);}
 @GetMapping("/posts") List<Map<String,Object>> posts(@RequestParam(defaultValue="")String kind,@RequestParam(defaultValue="")String q){return db.queryForList("SELECT p.*,u.name AS author,COALESCE(i.quantity,1) AS quantity,(p.price=0) AS is_free,COALESCE((SELECT AVG(r.rating) FROM product_reviews r WHERE r.post_id=p.id),0) AS product_rating,(SELECT COUNT(*) FROM product_reviews r WHERE r.post_id=p.id) AS product_review_count FROM posts p JOIN users u ON p.user_id=u.id LEFT JOIN post_inventory i ON i.post_id=p.id WHERE (?='' OR p.kind=?) AND (p.title LIKE ? OR p.description LIKE ?) ORDER BY p.created_at DESC",kind,kind,"%"+q+"%","%"+q+"%");}
 @GetMapping("/blogs") List<Map<String,Object>> blogs(){return db.queryForList("SELECT b.*,u.name AS author FROM blogs b JOIN users u ON b.user_id=u.id ORDER BY b.created_at DESC");}
 @PostMapping("/blogs") Map<String,Object> addBlog(@RequestBody Blog blog,HttpSession s){require(blog.title()!=null&&!blog.title().isBlank()&&blog.title().length()<=180&&blog.body()!=null&&!blog.body().isBlank()&&blog.body().length()<=20000,"Enter a title and blog text (up to 20,000 characters)");KeyHolder key=new GeneratedKeyHolder();db.update(connection->{PreparedStatement statement=connection.prepareStatement("INSERT INTO blogs(user_id,title,body) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS);statement.setLong(1,uid(s));statement.setString(2,blog.title().trim());statement.setString(3,blog.body().trim());return statement;},key);return Map.of("id",key.getKey().longValue(),"message","Blog published");}
 @GetMapping("/announcements") List<Map<String,Object>> announcements(){return db.queryForList("SELECT a.*,u.name AS author FROM campus_announcements a JOIN users u ON u.id=a.author_id ORDER BY a.created_at DESC,a.id DESC");}
 @PostMapping("/admin/announcements") Map<String,Object> addAnnouncement(@RequestBody Announcement announcement,HttpSession s){if(!admin(s))throw new ApiError(HttpStatus.FORBIDDEN,"Admin only");require(announcement.title()!=null&&!announcement.title().isBlank()&&announcement.title().length()<=180&&announcement.body()!=null&&!announcement.body().isBlank()&&announcement.body().length()<=4000,"Enter a title and announcement (up to 4,000 characters)");KeyHolder key=new GeneratedKeyHolder();db.update(connection->{PreparedStatement statement=connection.prepareStatement("INSERT INTO campus_announcements(author_id,title,body) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS);statement.setLong(1,uid(s));statement.setString(2,announcement.title().trim());statement.setString(3,announcement.body().trim());return statement;},key);return Map.of("id",key.getKey().longValue(),"message","Campus announcement published");}
 @GetMapping("/lost-found") List<Map<String,Object>> lostFound(){return db.queryForList("SELECT f.*,u.name AS author FROM lost_found_items f JOIN users u ON u.id=f.user_id ORDER BY (f.status='Open') DESC,f.created_at DESC");}
 @PostMapping("/lost-found") Map<String,Object> addLostFound(@RequestBody LostFoundEntry entry,HttpSession s){require(entry.kind()!=null&&Set.of("Lost","Found").contains(entry.kind()),"Choose Lost or Found");require(entry.title()!=null&&!entry.title().isBlank()&&entry.title().length()<=180&&entry.description()!=null&&!entry.description().isBlank()&&entry.description().length()<=4000&&entry.location()!=null&&!entry.location().isBlank(),"Enter a title, description and campus location");KeyHolder key=new GeneratedKeyHolder();db.update(connection->{PreparedStatement statement=connection.prepareStatement("INSERT INTO lost_found_items(user_id,kind,title,description,location) VALUES(?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS);statement.setLong(1,uid(s));statement.setString(2,entry.kind());statement.setString(3,entry.title().trim());statement.setString(4,entry.description().trim());statement.setString(5,entry.location().trim());return statement;},key);return Map.of("id",key.getKey().longValue(),"message","Lost and found post created");}
 @PostMapping("/lost-found/{id}/resolve") Map<String,String> resolveLostFound(@PathVariable long id,HttpSession s){long me=uid(s);Map<String,Object> item=one("SELECT user_id,status FROM lost_found_items WHERE id=?",id);require(num(item,"user_id")==me||admin(s),"Only the post owner or an admin can close this item");int changed=db.update("UPDATE lost_found_items SET status='Resolved' WHERE id=? AND status='Open'",id);require(changed==1,"This item is already closed");return Map.of("message","Lost and found post closed");}
 @GetMapping("/admin/analytics") Map<String,Object> adminAnalytics(HttpSession s){if(!admin(s))throw new ApiError(HttpStatus.FORBIDDEN,"Admin only");Map<String,Object> totals=one("SELECT (SELECT COUNT(*) FROM users WHERE suspended=FALSE) AS active_users,(SELECT COUNT(*) FROM posts) AS listings,(SELECT COUNT(*) FROM posts WHERE status='Open') AS open_listings,(SELECT COUNT(*) FROM deals) AS deals,(SELECT COUNT(*) FROM deals WHERE status IN ('Confirmed','Paid')) AS completed_deals,(SELECT COUNT(*) FROM lost_found_items WHERE status='Open') AS open_lost_found,(SELECT COUNT(*) FROM campus_announcements) AS announcements");List<Map<String,Object>> signups=db.queryForList("SELECT DATE_FORMAT(created_at,'%Y-%m-%d') AS day,COUNT(*) AS total FROM users WHERE created_at>=CURRENT_DATE-INTERVAL 6 DAY GROUP BY DATE(created_at) ORDER BY DATE(created_at)");List<Map<String,Object>> listingActivity=db.queryForList("SELECT DATE_FORMAT(created_at,'%Y-%m-%d') AS day,COUNT(*) AS total FROM posts WHERE created_at>=CURRENT_DATE-INTERVAL 6 DAY GROUP BY DATE(created_at) ORDER BY DATE(created_at)");List<Map<String,Object>> dealStatuses=db.queryForList("SELECT status,COUNT(*) AS total FROM deals GROUP BY status ORDER BY total DESC");List<Map<String,Object>> listingKinds=db.queryForList("SELECT kind,COUNT(*) AS total FROM posts GROUP BY kind ORDER BY total DESC");return Map.of("totals",totals,"signupsLast7Days",signups,"listingsLast7Days",listingActivity,"dealStatuses",dealStatuses,"listingKinds",listingKinds);}
 @GetMapping("/saved") List<Map<String,Object>> savedPosts(HttpSession s){return db.queryForList("SELECT p.*,u.name AS author,COALESCE(i.quantity,1) AS quantity,(p.price=0) AS is_free,COALESCE((SELECT AVG(r.rating) FROM product_reviews r WHERE r.post_id=p.id),0) AS product_rating,(SELECT COUNT(*) FROM product_reviews r WHERE r.post_id=p.id) AS product_review_count FROM saved_posts sp JOIN posts p ON p.id=sp.post_id JOIN users u ON u.id=p.user_id LEFT JOIN post_inventory i ON i.post_id=p.id WHERE sp.user_id=? ORDER BY sp.created_at DESC",uid(s));}
 @PostMapping("/posts/{id}/save") Map<String,String> savePost(@PathVariable long id,HttpSession s){long me=uid(s);one("SELECT id FROM posts WHERE id=?",id);db.update("INSERT IGNORE INTO saved_posts(user_id,post_id) VALUES(?,?)",me,id);return Map.of("message","Added to wishlist");}
 @DeleteMapping("/posts/{id}/save") Map<String,String> unsavePost(@PathVariable long id,HttpSession s){db.update("DELETE FROM saved_posts WHERE user_id=? AND post_id=?",uid(s),id);return Map.of("message","Removed from wishlist");}
 @GetMapping("/users") List<Map<String,Object>> users(HttpSession s){long me=uid(s);return db.queryForList("SELECT u.id,u.name,u.department,u.year_of_study,u.bio,(SELECT COUNT(*) FROM direct_messages dm WHERE dm.sender_id=u.id AND dm.recipient_id=? AND dm.read_at IS NULL) AS unread_count FROM users u WHERE u.id<>? AND u.suspended=FALSE ORDER BY u.name",me,me);}
 @GetMapping("/users/{id}/messages") List<Map<String,Object>> directMessages(@PathVariable long id,HttpSession s){long me=uid(s);require(id!=me,"You cannot start a chat with yourself");one("SELECT id FROM users WHERE id=? AND suspended=FALSE",id);List<Map<String,Object>> messages=db.queryForList("SELECT id,sender_id,recipient_id,body,created_at FROM direct_messages WHERE (sender_id=? AND recipient_id=?) OR (sender_id=? AND recipient_id=?) ORDER BY created_at,id",me,id,id,me);db.update("UPDATE direct_messages SET read_at=CURRENT_TIMESTAMP WHERE sender_id=? AND recipient_id=? AND read_at IS NULL",id,me);return messages;}
 @PostMapping("/users/{id}/messages") Map<String,String> sendDirectMessage(@PathVariable long id,@RequestBody Message m,HttpSession s){long me=uid(s);require(id!=me,"You cannot message yourself");one("SELECT id FROM users WHERE id=? AND suspended=FALSE",id);require(m.body()!=null&&!m.body().isBlank()&&m.body().length()<=2000,"Message must be 1–2000 characters");String body=m.body().trim();db.update("INSERT INTO direct_messages(sender_id,recipient_id,body) VALUES(?,?,?)",me,id,body);notifyUser(id,"New message from "+str(one("SELECT name FROM users WHERE id=?",me),"name"),"chat",me);return Map.of("message","Sent");}
 @GetMapping("/posts/{id}") Map<String,Object> post(@PathVariable long id){return one("SELECT p.*,u.name AS author,COALESCE(i.quantity,1) AS quantity,(p.price=0) AS is_free,COALESCE((SELECT AVG(r.rating) FROM product_reviews r WHERE r.post_id=p.id),0) AS product_rating,(SELECT COUNT(*) FROM product_reviews r WHERE r.post_id=p.id) AS product_review_count FROM posts p JOIN users u ON p.user_id=u.id LEFT JOIN post_inventory i ON i.post_id=p.id WHERE p.id=?",id);}
 @PostMapping("/posts") @Transactional Map<String,Object> addPost(@RequestBody Post p,HttpSession s){require(p.kind()!=null&&Set.of("market","task","delivery").contains(p.kind())&&p.title()!=null&&!p.title().isBlank()&&p.title().length()<=180&&p.description()!=null&&!p.description().isBlank()&&p.location()!=null&&!p.location().isBlank()&&p.price()!=null&&p.price()>=(p.kind().equals("market")?0:1)&&p.price()<=5000,"Complete all fields; market items may be free, while task and delivery prices must be positive and all prices must be at most INR 5,000");int quantity=p.kind().equals("market")&&p.quantity()!=null?p.quantity():1;require(quantity>=1&&quantity<=10000,"Quantity must be between 1 and 10,000");require(!p.kind().equals("delivery")||(p.destination()!=null&&!p.destination().isBlank()),"Enter a drop-off destination for pick & drop");KeyHolder key=new GeneratedKeyHolder();db.update(connection->{PreparedStatement statement=connection.prepareStatement("INSERT INTO posts(user_id,kind,title,description,category,price,location,destination) VALUES(?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS);statement.setLong(1,uid(s));statement.setString(2,p.kind());statement.setString(3,p.title().trim());statement.setString(4,p.description().trim());statement.setString(5,p.category());statement.setDouble(6,p.price());statement.setString(7,p.location().trim());statement.setString(8,p.destination()==null?"":p.destination().trim());return statement;},key);long postId=key.getKey().longValue();if(p.kind().equals("market"))db.update("INSERT INTO post_inventory(post_id,quantity) VALUES(?,?)",postId,quantity);return Map.of("id",postId,"message",p.kind().equals("delivery")?"Pick & drop request posted":"Listing created");}
 @PutMapping("/posts/{id}") @Transactional Map<String,Object> updateProduct(@PathVariable long id,@RequestBody Post p,HttpSession s){long me=uid(s);Map<String,Object> existing=one("SELECT user_id,kind,status FROM posts WHERE id=? FOR UPDATE",id);require(num(existing,"user_id")==me,"Only the seller can edit this listing");require("market".equals(str(existing,"kind"))&&"market".equals(p.kind()),"Only marketplace products can be edited here");require(Set.of("Open","Completed").contains(str(existing,"status")),"Only available or completed products can be edited");Long activeDeals=db.queryForObject("SELECT COUNT(*) FROM deals WHERE post_id=? AND status IN ('Accepted','In progress','Delivered','Confirmed')",Long.class,id);require(activeDeals==null||activeDeals==0,"This product cannot be edited while an accepted order is being completed");require(p.title()!=null&&!p.title().isBlank()&&p.title().length()<=180&&p.description()!=null&&!p.description().isBlank()&&p.location()!=null&&!p.location().isBlank()&&p.price()!=null&&p.price()>=0&&p.price()<=5000,"Enter a title, description, campus location, and price from INR 0 to INR 5,000");int quantity=p.quantity()==null?0:p.quantity();require(quantity>=0&&quantity<=10000,"Available quantity must be between 0 and 10,000");db.update("UPDATE posts SET title=?,description=?,category=?,price=?,location=? WHERE id=?",p.title().trim(),p.description().trim(),p.category()==null?"Other":p.category(),p.price(),p.location().trim(),id);db.update("UPDATE post_inventory SET quantity=? WHERE post_id=?",quantity,id);db.update("UPDATE posts SET status=? WHERE id=?",quantity==0?"Completed":"Open",id);return Map.of("id",id,"message","Product updated");}
 String attachmentType(String extension){return switch(extension){case "jpg","jpeg"->"image/jpeg";case "png"->"image/png";case "webp"->"image/webp";case "pdf"->"application/pdf";case "doc"->"application/msword";case "docx"->"application/vnd.openxmlformats-officedocument.wordprocessingml.document";case "ppt"->"application/vnd.ms-powerpoint";case "pptx"->"application/vnd.openxmlformats-officedocument.presentationml.presentation";case "xls"->"application/vnd.ms-excel";case "xlsx"->"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";case "txt"->"text/plain";case "csv"->"text/csv";default->throw new ApiError(HttpStatus.BAD_REQUEST,"Unsupported file type");};}
 @PostMapping(value="/posts/{id}/attachments",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) Map<String,Object> uploadAttachment(@PathVariable long id,@RequestParam("file")MultipartFile file,HttpSession s)throws IOException{long me=uid(s);Map<String,Object> listing=one("SELECT user_id FROM posts WHERE id=?",id);require(num(listing,"user_id")==me,"Only the listing owner can add attachments");require(!file.isEmpty()&&file.getSize()<=MAX_ATTACHMENT_BYTES,"Each attachment must be smaller than 10 MB");String original=file.getOriginalFilename();require(original!=null&&!original.isBlank(),"Choose a file");String extension=original.substring(original.lastIndexOf('.')+1).toLowerCase(Locale.ROOT);require(ATTACHMENT_TYPES.contains(extension),"Supported files: images, PDF, Word, PowerPoint, Excel, TXT and CSV");String contentType=attachmentType(extension);require(file.getContentType()==null||file.getContentType().isBlank()||file.getContentType().equalsIgnoreCase(contentType)||file.getContentType().equalsIgnoreCase("application/octet-stream"),"File type does not match its extension");Long count=db.queryForObject("SELECT COUNT(*) FROM post_attachments WHERE post_id=?",Long.class,id);require(count!=null&&count<5,"A listing can have up to 5 attachments");Path directory=Path.of(uploadDirectory).toAbsolutePath().normalize();Files.createDirectories(directory);String storedName=UUID.randomUUID()+"."+extension;Path destination=directory.resolve(storedName).normalize();require(destination.getParent().equals(directory),"Invalid upload path");Files.copy(file.getInputStream(),destination);try{db.update("INSERT INTO post_attachments(post_id,original_name,stored_name,content_type,file_size) VALUES(?,?,?,?,?)",id,original,storedName,contentType,file.getSize());}catch(DataAccessException e){Files.deleteIfExists(destination);throw e;}return Map.of("message","File added","name",original);}
 @GetMapping("/posts/{id}/attachments") List<Map<String,Object>> postAttachments(@PathVariable long id){one("SELECT id FROM posts WHERE id=?",id);return db.queryForList("SELECT id,original_name,content_type,file_size FROM post_attachments WHERE post_id=? ORDER BY id",id);}
 @GetMapping("/attachments/{id}") ResponseEntity<FileSystemResource> getAttachment(@PathVariable long id){Map<String,Object> attachment=one("SELECT stored_name,original_name,content_type FROM post_attachments WHERE id=?",id);Path file=Path.of(uploadDirectory).toAbsolutePath().normalize().resolve(str(attachment,"stored_name")).normalize();if(!file.startsWith(Path.of(uploadDirectory).toAbsolutePath().normalize())||!Files.isRegularFile(file))throw new ApiError(HttpStatus.NOT_FOUND,"File not found");String type=str(attachment,"content_type");String disposition=type.startsWith("image/")||type.equals("application/pdf")?"inline":"attachment";String name=URLEncoder.encode(str(attachment,"original_name"),StandardCharsets.UTF_8).replace("+","%20");return ResponseEntity.ok().contentType(MediaType.parseMediaType(type)).header(HttpHeaders.CONTENT_DISPOSITION,disposition+"; filename*=UTF-8''"+name).body(new FileSystemResource(file));}
 @GetMapping("/my-posts") List<Map<String,Object>> myPosts(HttpSession s){return db.queryForList("SELECT p.*,COALESCE(i.quantity,1) AS quantity,(p.price=0) AS is_free,COALESCE((SELECT AVG(r.rating) FROM product_reviews r WHERE r.post_id=p.id),0) AS product_rating,(SELECT COUNT(*) FROM product_reviews r WHERE r.post_id=p.id) AS product_review_count FROM posts p LEFT JOIN post_inventory i ON i.post_id=p.id WHERE p.user_id=? ORDER BY p.created_at DESC",uid(s));}
 @Transactional @PostMapping("/posts/{id}/request") Map<String,Object> request(@PathVariable long id,@RequestBody(required=false) OfferRequest offer,HttpSession s){long me=uid(s);Map<String,Object> p=one("SELECT p.*,COALESCE(i.quantity,1) AS quantity FROM posts p LEFT JOIN post_inventory i ON i.post_id=p.id WHERE p.id=? FOR UPDATE",id);require("Open".equals(p.get("status"))&&num(p,"user_id")!=me,"Cannot request this listing");int quantity=!str(p,"kind").equals("market")||offer==null||offer.quantity()==null?1:offer.quantity();require(quantity>=1&&quantity<=10000,"Requested quantity must be between 1 and 10,000");if(str(p,"kind").equals("market"))require(quantity<=num(p,"quantity"),"Requested quantity exceeds available stock");db.update("INSERT INTO deals(post_id,owner_id,worker_id) VALUES(?,?,?)",id,num(p,"user_id"),me);long dealId=num(one("SELECT LAST_INSERT_ID() AS id"),"id");db.update("INSERT INTO deal_quantities(deal_id,quantity) VALUES(?,?)",dealId,quantity);String kind=str(p,"kind");notifyUser(num(p,"user_id"),kind.equals("task")?"A student volunteered for your task: "+p.get("title"):"New request: "+p.get("title"),"deal",dealId);return Map.of("message",kind.equals("task")?"Your volunteer offer was sent":"Request sent");}
 @GetMapping("/deals") List<Map<String,Object>> deals(HttpSession s){long me=uid(s);return db.queryForList("SELECT d.*,COALESCE(dq.quantity,1) AS quantity,EXISTS(SELECT 1 FROM reviews r WHERE r.deal_id=d.id AND r.author_id=?) AS reviewed_by_me,EXISTS(SELECT 1 FROM product_reviews r WHERE r.post_id=p.id AND r.reviewer_id=?) AS product_reviewed_by_me,p.title,p.price,p.price*COALESCE(dq.quantity,1) AS total_price,p.kind,p.location,p.destination,owner.name owner_name,worker.name worker_name FROM deals d LEFT JOIN deal_quantities dq ON dq.deal_id=d.id JOIN posts p ON p.id=d.post_id JOIN users owner ON owner.id=d.owner_id JOIN users worker ON worker.id=d.worker_id WHERE d.owner_id=? OR d.worker_id=? ORDER BY d.updated_at DESC",me,me,me,me);}
 Map<String,Object> deal(long id,HttpSession s){long me=uid(s);Map<String,Object> d=one("SELECT d.*,COALESCE(dq.quantity,1) AS quantity,EXISTS(SELECT 1 FROM reviews r WHERE r.deal_id=d.id AND r.author_id=?) AS reviewed_by_me,EXISTS(SELECT 1 FROM product_reviews r WHERE r.post_id=p.id AND r.reviewer_id=?) AS product_reviewed_by_me,p.title,p.price,p.price*COALESCE(dq.quantity,1) AS total_price,p.kind,p.location,p.destination FROM deals d LEFT JOIN deal_quantities dq ON dq.deal_id=d.id JOIN posts p ON p.id=d.post_id WHERE d.id=?",me,me,id);if(num(d,"owner_id")!=me&&num(d,"worker_id")!=me)throw new ApiError(HttpStatus.FORBIDDEN,"Not your deal");return d;}
 @GetMapping("/deals/{id}") Map<String,Object> dealView(@PathVariable long id,HttpSession s){return deal(id,s);}
 @PostMapping("/deals/{id}/tracking") Map<String,String> updateDeliveryLocation(@PathVariable long id,@RequestBody LocationUpdate location,HttpSession s){Map<String,Object>d=deal(id,s);require(num(d,"worker_id")==uid(s)&&"delivery".equals(str(d,"kind"))&&"In progress".equals(str(d,"status")),"Only the delivery volunteer can share location during an active delivery");require(location.latitude()!=null&&location.latitude()>=-90&&location.latitude()<=90&&location.longitude()!=null&&location.longitude()>=-180&&location.longitude()<=180,"Provide valid GPS coordinates");db.update("INSERT INTO delivery_locations(deal_id,latitude,longitude) VALUES(?,?,?) ON DUPLICATE KEY UPDATE latitude=VALUES(latitude),longitude=VALUES(longitude),updated_at=CURRENT_TIMESTAMP",id,location.latitude(),location.longitude());return Map.of("message","Live location shared");}
 @GetMapping("/deals/{id}/tracking") Map<String,Object> deliveryLocation(@PathVariable long id,HttpSession s){Map<String,Object>d=deal(id,s);require("delivery".equals(str(d,"kind"))&&"In progress".equals(str(d,"status")),"Live tracking is only available during an active delivery");List<Map<String,Object>> location=db.queryForList("SELECT latitude,longitude,updated_at FROM delivery_locations WHERE deal_id=? AND updated_at>=CURRENT_TIMESTAMP-INTERVAL 30 SECOND",id);if(location.isEmpty())return Map.of("sharing",false);Map<String,Object> result=new HashMap<>(location.get(0));result.put("sharing",true);return result;}
 @DeleteMapping("/deals/{id}/tracking") Map<String,String> stopDeliveryLocation(@PathVariable long id,HttpSession s){Map<String,Object>d=deal(id,s);require(num(d,"worker_id")==uid(s)&&"delivery".equals(str(d,"kind")),"Only the delivery volunteer can stop location sharing");db.update("DELETE FROM delivery_locations WHERE deal_id=?",id);return Map.of("message","Live location sharing stopped");}
 @Transactional @PostMapping("/deals/{id}/status") Map<String,Object> status(@PathVariable long id,@RequestBody Map<String,String> input,HttpSession s){Map<String,Object> d=deal(id,s);long me=uid(s);String current=str(d,"status"),next=input.getOrDefault("status","");boolean owner=num(d,"owner_id")==me,worker=num(d,"worker_id")==me;boolean allowed=(current.equals("Requested")&&owner&&Set.of("Accepted","Cancelled").contains(next))||(current.equals("Accepted")&&owner&&next.equals("In progress"))||(current.equals("In progress")&&owner&&next.equals("Delivered"))||(current.equals("Delivered")&&worker&&next.equals("Confirmed"))||(current.equals("Confirmed")&&worker&&next.equals("Paid"));require(allowed,"Status change not allowed");String otp=next.equals("Delivered")?String.format("%06d",rng.nextInt(1000000)):null;
 if(next.equals("Accepted")&&!str(d,"kind").equals("market"))db.update("UPDATE posts SET status='Matched' WHERE id=?",num(d,"post_id"));
 if(next.equals("Accepted")&&str(d,"kind").equals("market")){long postId=num(d,"post_id");List<Map<String,Object>> stock=db.queryForList("SELECT quantity FROM post_inventory WHERE post_id=? FOR UPDATE",postId);if(stock.isEmpty())db.update("INSERT INTO post_inventory(post_id,quantity) VALUES(?,1)",postId);int requestedQuantity=(int)num(d,"quantity");int changed=db.update("UPDATE post_inventory SET quantity=quantity-? WHERE post_id=? AND quantity>=?",requestedQuantity,postId,requestedQuantity);require(changed==1,"Not enough stock remains to accept this request");int remaining=db.queryForObject("SELECT quantity FROM post_inventory WHERE post_id=?",Integer.class,postId);List<Map<String,Object>> rejectedOffers=db.queryForList("SELECT id,worker_id FROM deals WHERE post_id=? AND id<>? AND status='Requested'",postId,id);db.update("UPDATE deals SET status='Cancelled' WHERE post_id=? AND id<>? AND status='Requested'",postId,id);for(Map<String,Object> rejectedOffer:rejectedOffers)notifyUser(num(rejectedOffer,"worker_id"),"Your request for "+str(d,"title")+" was declined because another offer was accepted","deal",num(rejectedOffer,"id"));db.update("UPDATE posts SET status=? WHERE id=?",remaining==0?"Matched":"Open",postId);}
 int changed=db.update("UPDATE deals SET status=?,otp=COALESCE(?,otp) WHERE id=? AND status=?",next,otp,id,current);require(changed==1,"This request was updated by another action; refresh and try again");if(next.equals("Delivered")&&"delivery".equals(str(d,"kind")))db.update("DELETE FROM delivery_locations WHERE deal_id=?",id);if(next.equals("Paid")&&!str(d,"kind").equals("market"))db.update("UPDATE posts SET status='Completed' WHERE id=?",num(d,"post_id"));if(next.equals("Paid")&&str(d,"kind").equals("market")&&num(one("SELECT quantity FROM post_inventory WHERE post_id=?",num(d,"post_id")),"quantity")==0)db.update("UPDATE posts SET status='Completed' WHERE id=?",num(d,"post_id"));notifyUser(owner?num(d,"worker_id"):num(d,"owner_id"),"Deal #"+id+" updated: "+next,"deal",id);return Map.of("message","Updated to "+next+" (Paid is a demo status, not a real transfer)");}
 @GetMapping("/deals/{id}/messages") List<Map<String,Object>> messages(@PathVariable long id,HttpSession s){deal(id,s);return db.queryForList("SELECT m.*,u.name sender FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.deal_id=? ORDER BY m.created_at",id);}
 @PostMapping("/deals/{id}/messages") Map<String,String> message(@PathVariable long id,@RequestBody Message m,HttpSession s){Map<String,Object>d=deal(id,s);require(m.body()!=null&&!m.body().isBlank()&&m.body().length()<=2000,"Message must be 1–2000 characters");long me=uid(s);db.update("INSERT INTO messages(deal_id,sender_id,body) VALUES(?,?,?)",id,me,m.body().trim());notifyUser(num(d,"owner_id")==me?num(d,"worker_id"):num(d,"owner_id"),"New message in deal #"+id,"deal",id);return Map.of("message","Sent");}
 @PostMapping("/deals/{id}/reviews") Map<String,String> review(@PathVariable long id,@RequestBody Review r,HttpSession s){Map<String,Object>d=deal(id,s);require(Set.of("Confirmed","Paid").contains(str(d,"status"))&&r.rating()!=null&&r.rating()>=1&&r.rating()<=5,"Review only confirmed deals with 1–5 stars");require(r.body()==null||r.body().length()<=2000,"Review must be 2,000 characters or fewer");long me=uid(s);long target=num(d,"owner_id")==me?num(d,"worker_id"):num(d,"owner_id");db.update("INSERT INTO reviews(deal_id,author_id,target_id,rating,body) VALUES(?,?,?,?,?)",id,me,target,r.rating(),r.body()==null?null:r.body().trim());return Map.of("message","Review submitted");}
 @GetMapping("/users/{id}/reviews") Map<String,Object> userReviews(@PathVariable long id){one("SELECT id FROM users WHERE id=? AND suspended=FALSE",id);List<Map<String,Object>> items=db.queryForList("SELECT r.id,r.rating,r.body,r.created_at,u.name AS author,p.title FROM reviews r JOIN users u ON u.id=r.author_id JOIN deals d ON d.id=r.deal_id JOIN posts p ON p.id=d.post_id WHERE r.target_id=? ORDER BY r.created_at DESC",id);Double average=db.queryForObject("SELECT AVG(rating) FROM reviews WHERE target_id=?",Double.class,id);return Map.of("average",average==null?0:average,"count",items.size(),"reviews",items);}
 @GetMapping("/posts/{id}/reviews") Map<String,Object> productReviews(@PathVariable long id){one("SELECT id FROM posts WHERE id=? AND kind='market'",id);List<Map<String,Object>> items=db.queryForList("SELECT r.id,r.rating,r.body,r.created_at,u.name AS author FROM product_reviews r JOIN users u ON u.id=r.reviewer_id WHERE r.post_id=? ORDER BY r.created_at DESC",id);Double average=db.queryForObject("SELECT AVG(rating) FROM product_reviews WHERE post_id=?",Double.class,id);return Map.of("average",average==null?0:average,"count",items.size(),"reviews",items);}
 @PostMapping("/deals/{id}/product-review") Map<String,String> productReview(@PathVariable long id,@RequestBody ProductReview r,HttpSession s){Map<String,Object>d=deal(id,s);long me=uid(s);require(num(d,"worker_id")==me&&"market".equals(str(d,"kind"))&&Set.of("Confirmed","Paid").contains(str(d,"status")),"Only the buyer of a completed product order can rate this product");require(r.rating()!=null&&r.rating()>=1&&r.rating()<=5,"Choose a 1–5 star product rating");require(r.body()!=null&&!r.body().isBlank()&&r.body().length()<=2000,"Write a product review of up to 2,000 characters");db.update("INSERT INTO product_reviews(post_id,deal_id,reviewer_id,rating,body) VALUES(?,?,?,?,?)",num(d,"post_id"),id,me,r.rating(),r.body().trim());return Map.of("message","Product rating submitted");}
 @PostMapping("/support-tickets") Map<String,String> supportTicket(@RequestBody SupportTicket ticket,HttpSession s){require(ticket.subject()!=null&&!ticket.subject().isBlank()&&ticket.subject().length()<=160&&ticket.details()!=null&&!ticket.details().isBlank()&&ticket.details().length()<=4000,"Enter a subject and details (up to 4,000 characters)");long me=uid(s);db.update("INSERT INTO support_tickets(user_id,subject,details) VALUES(?,?,?)",me,ticket.subject().trim(),ticket.details().trim());for(long adminId:db.queryForList("SELECT id FROM users WHERE is_admin=TRUE AND suspended=FALSE",Long.class))notifyUser(adminId,"A support request needs attention","admin",null);return Map.of("message","Support request sent");}
 @GetMapping("/support-tickets") List<Map<String,Object>> mySupportTickets(HttpSession s){return db.queryForList("SELECT id,subject,details,status,created_at FROM support_tickets WHERE user_id=? ORDER BY created_at DESC",uid(s));}
 @PostMapping("/safety-reports") Map<String,String> safetyReport(@RequestBody SafetyReport report,HttpSession s){long me=uid(s);require(report.category()!=null&&Set.of("Unsafe behavior","Harassment","Fraud or scam","Suspicious listing","Other").contains(report.category()),"Choose a safety report category");require(report.details()!=null&&!report.details().isBlank()&&report.details().length()<=4000,"Describe the safety concern (up to 4,000 characters)");if(report.postId()!=null)one("SELECT id FROM posts WHERE id=?",report.postId());if(report.userId()!=null){require(report.userId()!=me,"You cannot report yourself");one("SELECT id FROM users WHERE id=? AND suspended=FALSE",report.userId());}if(report.postId()==null&&report.userId()==null)throw new ApiError(HttpStatus.BAD_REQUEST,"Select a listing or user to report");db.update("INSERT INTO safety_reports(reporter_id,post_id,reported_user_id,category,details) VALUES(?,?,?,?,?)",me,report.postId(),report.userId(),report.category(),report.details().trim());for(long adminId:db.queryForList("SELECT id FROM users WHERE is_admin=TRUE AND suspended=FALSE",Long.class))notifyUser(adminId,"A new safety report needs review","admin",null);return Map.of("message","Safety report submitted for review");}
 @GetMapping("/safety-reports") List<Map<String,Object>> mySafetyReports(HttpSession s){return db.queryForList("SELECT * FROM safety_reports WHERE reporter_id=? ORDER BY created_at DESC",uid(s));}
 @Transactional @PostMapping("/deals/{id}/disputes") Map<String,String> openDispute(@PathVariable long id,@RequestBody Dispute dispute,HttpSession s){Map<String,Object>d=deal(id,s);long me=uid(s);String current=str(one("SELECT status FROM deals WHERE id=? FOR UPDATE",id),"status");require(dispute.details()!=null&&!dispute.details().isBlank()&&dispute.details().length()<=4000,"Describe the order dispute (up to 4,000 characters)");require(!Set.of("Cancelled","Disputed").contains(current),"This order cannot be disputed");Long existing=db.queryForObject("SELECT COUNT(*) FROM disputes WHERE deal_id=? AND status='Open'",Long.class,id);require(existing==null||existing==0,"This order already has an open dispute");db.update("INSERT INTO disputes(deal_id,opened_by,details,deal_status_before) VALUES(?,?,?,?)",id,me,dispute.details().trim(),current);int changed=db.update("UPDATE deals SET status='Disputed' WHERE id=? AND status=?",id,current);require(changed==1,"This order changed; refresh and retry");long other=num(d,"owner_id")==me?num(d,"worker_id"):num(d,"owner_id");notifyUser(other,"A dispute was opened for deal #"+id,"deal",id);return Map.of("message","Dispute submitted; the order is paused for review");}
 @GetMapping("/deals/{id}/disputes") List<Map<String,Object>> dealDisputes(@PathVariable long id,HttpSession s){deal(id,s);return db.queryForList("SELECT d.*,u.name AS opened_by_name FROM disputes d JOIN users u ON u.id=d.opened_by WHERE d.deal_id=? ORDER BY d.created_at DESC",id);}
 @GetMapping("/disputes") List<Map<String,Object>> myDisputes(HttpSession s){return db.queryForList("SELECT d.*,p.title,opener.name AS opened_by_name FROM disputes d JOIN deals o ON o.id=d.deal_id JOIN posts p ON p.id=o.post_id JOIN users opener ON opener.id=d.opened_by WHERE o.owner_id=? OR o.worker_id=? ORDER BY d.created_at DESC",uid(s),uid(s));}
 @GetMapping("/notifications") List<Map<String,Object>> notifications(HttpSession s){return db.queryForList("SELECT n.*,t.event_type,t.event_id FROM notifications n LEFT JOIN notification_targets t ON t.notification_id=n.id WHERE n.user_id=? ORDER BY n.created_at DESC,n.id DESC",uid(s));}
 @PostMapping("/notifications/read") Map<String,String> markNotificationsRead(HttpSession s){db.update("UPDATE notifications SET is_read=TRUE WHERE user_id=?",uid(s));return Map.of("message","Notifications marked as read");}
 @PostMapping("/reports") Map<String,String> report(@RequestBody Report r,HttpSession s){require(r.reason()!=null&&!r.reason().isBlank(),"Reason required");db.update("INSERT INTO reports(reporter_id,post_id,reason) VALUES(?,?,?)",uid(s),r.postId(),r.reason());return Map.of("message","Report submitted");}
 boolean admin(HttpSession s){return Boolean.TRUE.equals(me(s).get("is_admin"));}
 @GetMapping("/admin/reports") List<Map<String,Object>> reports(HttpSession s){if(!admin(s))throw new ApiError(HttpStatus.FORBIDDEN,"Admin only");return db.queryForList("SELECT r.*,u.name AS reporter_name,p.title AS post_title FROM reports r JOIN users u ON u.id=r.reporter_id LEFT JOIN posts p ON p.id=r.post_id ORDER BY r.created_at DESC");}
 @PostMapping("/admin/reports/{id}/resolve") Map<String,String> resolve(@PathVariable long id,HttpSession s){if(!admin(s))throw new ApiError(HttpStatus.FORBIDDEN,"Admin only");int changed=db.update("UPDATE reports SET status='Resolved' WHERE id=? AND status='Open'",id);require(changed==1,"Report is already resolved or not found");return Map.of("message","Report resolved");}
 @GetMapping("/admin/support-tickets") List<Map<String,Object>> adminSupportTickets(HttpSession s){if(!admin(s))throw new ApiError(HttpStatus.FORBIDDEN,"Admin only");return db.queryForList("SELECT t.*,u.name AS requester_name,u.email AS requester_email FROM support_tickets t JOIN users u ON u.id=t.user_id ORDER BY t.created_at DESC");}
 @PostMapping("/admin/support-tickets/{id}/resolve") Map<String,String> resolveSupportTicket(@PathVariable long id,HttpSession s){if(!admin(s))throw new ApiError(HttpStatus.FORBIDDEN,"Admin only");Map<String,Object> ticket=one("SELECT user_id FROM support_tickets WHERE id=? AND status='Open'",id);int changed=db.update("UPDATE support_tickets SET status='Resolved' WHERE id=? AND status='Open'",id);require(changed==1,"Support request is already resolved or not found");notifyUser(num(ticket,"user_id"),"Your support request #"+id+" was resolved","support",id);return Map.of("message","Support request resolved");}
 @GetMapping("/admin/safety-reports") List<Map<String,Object>> adminSafetyReports(HttpSession s){if(!admin(s))throw new ApiError(HttpStatus.FORBIDDEN,"Admin only");return db.queryForList("SELECT r.*,reporter.name AS reporter_name,reported.name AS reported_user_name,p.title AS post_title FROM safety_reports r JOIN users reporter ON reporter.id=r.reporter_id LEFT JOIN users reported ON reported.id=r.reported_user_id LEFT JOIN posts p ON p.id=r.post_id ORDER BY r.created_at DESC");}
 @PostMapping("/admin/safety-reports/{id}/resolve") Map<String,String> resolveSafetyReport(@PathVariable long id,HttpSession s){if(!admin(s))throw new ApiError(HttpStatus.FORBIDDEN,"Admin only");int changed=db.update("UPDATE safety_reports SET status='Resolved' WHERE id=? AND status='Open'",id);require(changed==1,"Safety report is already resolved or not found");return Map.of("message","Safety report resolved");}
 @GetMapping("/admin/disputes") List<Map<String,Object>> adminDisputes(HttpSession s){if(!admin(s))throw new ApiError(HttpStatus.FORBIDDEN,"Admin only");return db.queryForList("SELECT d.*,p.title,opener.name AS opened_by_name FROM disputes d JOIN deals o ON o.id=d.deal_id JOIN posts p ON p.id=o.post_id JOIN users opener ON opener.id=d.opened_by ORDER BY d.created_at DESC");}
 @Transactional @PostMapping("/admin/disputes/{id}/resolve") Map<String,String> resolveDispute(@PathVariable long id,@RequestBody Map<String,String> input,HttpSession s){if(!admin(s))throw new ApiError(HttpStatus.FORBIDDEN,"Admin only");String resolution=input.getOrDefault("resolution","").trim(),decision=input.getOrDefault("decision","");require(!resolution.isBlank()&&resolution.length()<=1000,"Enter a resolution (up to 1,000 characters)");require(Set.of("Resume","Cancel").contains(decision),"Choose whether to resume or cancel the order");Map<String,Object> dispute=one("SELECT deal_id,deal_status_before FROM disputes WHERE id=? AND status='Open' FOR UPDATE",id);long dealId=num(dispute,"deal_id");Map<String,Object>d=one("SELECT d.owner_id,d.worker_id,d.post_id,p.kind,COALESCE(q.quantity,1) AS quantity FROM deals d LEFT JOIN deal_quantities q ON q.deal_id=d.id JOIN posts p ON p.id=d.post_id WHERE d.id=?",dealId);if(decision.equals("Cancel")){if(str(d,"kind").equals("market")&&!str(dispute,"deal_status_before").equals("Requested")){db.update("UPDATE post_inventory SET quantity=quantity+? WHERE post_id=?",num(d,"quantity"),num(d,"post_id"));int restored=db.queryForObject("SELECT quantity FROM post_inventory WHERE post_id=?",Integer.class,num(d,"post_id"));db.update("UPDATE posts SET status=? WHERE id=?",restored>0?"Open":"Matched",num(d,"post_id"));}else if(!str(d,"kind").equals("market"))db.update("UPDATE posts SET status='Open' WHERE id=? AND status='Matched'",num(d,"post_id"));int cancelled=db.update("UPDATE deals SET status='Cancelled' WHERE id=? AND status='Disputed'",dealId);require(cancelled==1,"Dispute changed before resolution");}else db.update("UPDATE deals SET status=? WHERE id=? AND status='Disputed'",str(dispute,"deal_status_before"),dealId);db.update("UPDATE disputes SET status='Resolved',resolution=?,resolved_at=CURRENT_TIMESTAMP WHERE id=?",resolution,id);String outcome="Resume".equals(decision)?"resumed":"cancelled";notifyUser(num(d,"owner_id"),"Dispute #"+id+" resolved; order "+outcome+": "+resolution,"deal",dealId);notifyUser(num(d,"worker_id"),"Dispute #"+id+" resolved; order "+outcome+": "+resolution,"deal",dealId);return Map.of("message","Dispute resolved; order "+outcome);}
 @ExceptionHandler(ApiError.class) ResponseEntity<Map<String,String>> error(ApiError e){return ResponseEntity.status(e.status).body(Map.of("error",e.getMessage()));}
 @ExceptionHandler(org.springframework.dao.DataIntegrityViolationException.class) ResponseEntity<Map<String,String>> duplicate(Exception e){return ResponseEntity.badRequest().body(Map.of("error","Duplicate email, college ID, request or review, or invalid database value"));}
 static class ApiError extends RuntimeException {final HttpStatus status;ApiError(HttpStatus status,String message){super(message);this.status=status;}}
}
